import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Companies — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Companies — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/companies"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Companies — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/companies"}]]},"headers":[],"relativePath":"user-guide/companies.md","filePath":"user-guide/companies.md","lastUpdated":1788612600000}'),s={name:"user-guide/companies.md"};function i(r,e,c,l,d,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="companies-—-user-guide" tabindex="-1">Companies — User Guide <a class="header-anchor" href="#companies-—-user-guide" aria-label="Permalink to &quot;Companies — User Guide&quot;">​</a></h1><h2 id="who-can-use-companies" tabindex="-1">Who can use Companies <a class="header-anchor" href="#who-can-use-companies" aria-label="Permalink to &quot;Who can use Companies&quot;">​</a></h2><p>Your workspace must have the <strong>Companies</strong> module installed. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code> as needed).</p><p>Without <strong>assign</strong>, you only see companies assigned to you.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Companies</strong> from the sidebar under <strong>CRM</strong> (between Leads and Contacts).</p><ul><li>Search by name, email, phone, website, or industry</li><li>Filter by industry and assignee, or toggle <strong>My Companies</strong></li><li>KPI cards summarize total companies, my companies, unassigned, with email, and created this week</li><li>The table shows the <strong>latest note</strong>; hover a truncated preview to read the full note</li><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted company from the row menu</li><li><strong>Delete permanently</strong> (force delete) requires <code>companies.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New company</strong></li><li>Enter name (required) and optional email, phone, website, industry, address, source, and assignee</li><li>Save</li></ol><p>Edit from the row menu or the record page.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the record page or the create/edit form.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the company</li><li><strong>Activity</strong> — timeline of create, update, assignment, note, and delete/restore events</li></ul><h2 id="linking-contacts" tabindex="-1">Linking Contacts <a class="header-anchor" href="#linking-contacts" aria-label="Permalink to &quot;Linking Contacts&quot;">​</a></h2><p>On a Contact create/edit form, when Companies is installed and you have <code>companies.view</code>, pick a <strong>Company</strong> from the picker. Use <strong>New</strong> (requires <code>companies.create</code>) to create a company in a dialog without leaving the contact form — the new company is selected automatically. The contact’s legacy company text field is kept in sync with the linked Company’s name. The company record page lists linked contacts.</p>',16)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
